def _canonicalize_args(args: Any) -> Any:
    """Recursively canonicalize tool call arguments for stable fingerprinting.

    - Sorts dict keys recursively.
    - Converts tuples to lists for consistency.
    - Strips leading/trailing whitespace from string values.
    - Leaves numeric, boolean, and ``None`` values unchanged (no type coercion).
    """
    if isinstance(args, dict):
        return {k: _canonicalize_args(v) for k, v in sorted(args.items())}
    if isinstance(args, (list, tuple)):
        return [_canonicalize_args(item) for item in args]
    if isinstance(args, str):
        return args.strip()
    return args


class ToolCalls(Type):
    class ToolCall(BaseModel):
        name: str
        args: dict[str, Any]
        fingerprint: str = ""
        id: str = ""

        def __init__(self, /, **data):
            data.pop("fingerprint", None)
            data.pop("id", None)
            super().__init__(**data)
            canonical_args = _canonicalize_args(self.args)
            canonical_repr = {"name": self.name, "args": canonical_args}
            serialized = json.dumps(canonical_repr, sort_keys=True, separators=(",", ":"))
            fingerprint = hashlib.sha256(serialized.encode("utf-8")).hexdigest()
            self.fingerprint = fingerprint
            self.id = fingerprint[:8]

    tool_calls: list[ToolCall]

    @classmethod
    def validate_input(cls, data: Any) -> Any:
        """Normalize varied LM output formats into the canonical tool-calls structure.

        Handles the following input forms:
        - A dict with a ``tool_calls`` key (returned as-is).
        - A single ``{"name": ..., "args": ...}`` dict (wrapped under ``tool_calls``).
        - A bare list of ``{"name": ..., "args": ...}`` dicts (wrapped in a ``tool_calls`` container).
        - A plain JSON string (parsed, then normalized).
        - A non-JSON string (returned unchanged).

        Returns normalized Python structures (dict/list/string), not a ``ToolCalls`` instance.
        """
        if isinstance(data, str):
            try:
                data = json.loads(data)
            except (json.JSONDecodeError, ValueError):
                return data

        if isinstance(data, dict):
            if "tool_calls" in data:
                return data
            if "name" in data and "args" in data:
                return {"tool_calls": [data]}
            return data

        if isinstance(data, list):
            if all(isinstance(item, dict) and "name" in item and "args" in item for item in data):
                return {"tool_calls": data}
            return data

        return data

    @classmethod
    def from_dict_list(cls, tool_calls_dicts: list[dict[str, Any]]) -> "ToolCalls":
        """Convert a list of dictionaries to a ToolCalls instance.

        Args:
            dict_list: A list of dictionaries, where each dictionary should have 'name' and 'args' keys.

        Returns:
            A ToolCalls instance.

        Example:

            ```python
            tool_calls_dict = [
                {"name": "search", "args": {"query": "hello"}},
                {"name": "translate", "args": {"text": "world"}}
            ]
            tool_calls = ToolCalls.from_dict_list(tool_calls_dict)
            ```
        """
        tool_calls = [cls.ToolCall(**item) for item in tool_calls_dicts]
        return cls(tool_calls=tool_calls)
